// Brand marks, embedded so the pack makes no external requests.
//
// OTR lockup: the supplied master (OTR_earthmovertyres_logo_exact.svg), put into
// the reverse-on-black state the manual sets as default. The supplied file is an
// SVG wrapper around a raster, so this is that raster trimmed, inverted to white
// and keyed to transparency, with the orange lens arc, dot and full stop held at
// #FB8C1F. Replace with the Gate 1 vector master when it is drawn.
//
// Jewell tread: the endorsement mark, taken from the brand manual PDF and keyed
// to transparency in safety amber #FEC013. Endorsement use only.
//
// Rules honoured, section 03: full lockup used whole at every size, never
// cropped to an icon, never set in capitals, minimum 160px wide on screen.

const OTR_SRC = 'data:image/png;base64,';
const TREAD_SRC = 'data:image/png;base64,';

// Both marks are declared once per document as CSS backgrounds, so the artwork
// is not repeated for every sheet that shows it.
export function markStyles() {
  return `
  .otr-logo{display:block;background:url("${OTR_SRC}") left center/contain no-repeat;
    aspect-ratio:614/338;max-width:100%}
  .jt-tread{display:block;background:url("${TREAD_SRC}") center/contain no-repeat;
    aspect-ratio:192/298;flex-shrink:0}`;
}

export function otrLogo({ width = 200 } = {}) {
  return `<span class="otr-logo" style="width:${width}px" role="img"
     aria-label="OTR earthmovertyres.com"></span>`;
}

export function jewellTread({ height = 30 } = {}) {
  return `<span class="jt-tread" style="height:${height}px" aria-hidden="true"></span>`;
}

// Endorsement lockup: tread left, type right. Never leads, never outsizes the
// OTR wordmark, one per surface.
export function poweredByJewell({ height = 30, className = 'jt-endorse' } = {}) {
  return `<span class="${className}">${jewellTread({ height })}<span class="jt-type"><small>Powered by</small><b>Jewell Tyres</b></span></span>`;
}
